function Student({tab,p,d,refresh}){let i=d.ints[0],a=d.apps[0],hours=d.att.reduce((s,x)=>s+Number(x.hours||0),0);if(tab==="Dashboard")return <><section className="heroCard"><div className="heroContent"><span className="pill">SHIVORIX • INTERNSHIP PROGRAMME</span><h2>Welcome, {p.full_name?.split(" ")[0]}.</h2><p>Everything here is connected to your verified internship record.</p><b className="liveBadge">● LIVE ACCOUNT DATA</b></div><img src="/shivorix-logo.svg" className="heroOfficialLogo" alt="SHIVORIX"/></section><div className="stats"><Stat l="APPLICATION" v={a?.status||"Not submitted"} n={a?.application_number||"Start application"}/><Stat l="HOURS" v={Math.round(hours)+" / "+(i?.total_hours||120)} n="Recorded"/><Stat l="DOCUMENTS" v={d.docs.filter(x=>x.verification_status==="verified").length+"/5"} n="Verified"/><Stat l="EVALUATION" v={d.evals[0]?.rating||"Pending"} n="Performance"/></div><div className="grid2"><Card k="PROGRAMME" title="Internship overview"><Row k="Sector" v={i?.domain}/><Row k="Mode" v={i?.mode}/><Row k="Duration" v={i?(i.start_date+" → "+i.end_date):"Pending"}/><Row k="Credits" v={i?.credits||4}/></Card><Card k="COMPLETION" title="Progress"><div className="progress"><span style={{width:Math.min(100,Math.round(hours/(i?.total_hours||120)*100))+"%"}}/></div><div className="progressMeta"><span>Internship hours</span><b>{Math.round(hours)} / {i?.total_hours||120}</b></div><Row k="Final Test" v="Pending / result appears here"/><Row k="Certificate" v={d.certs[0]?.certificate_number||"Auto-generated on completion"}/></Card></div></>;if(tab==="My Profile")return <Profile p={p}/>;if(tab==="SHIVORIX IPO")return <Programme/>;if(tab==="Guidelines")return <Guidelines/>;if(tab==="Apply for Internship")return <Apply p={p} d={d} refresh={refresh}/>;if(tab==="My Application")return <Applications d={d}/>;if(tab==="Internship Details")return <Card k="ACTIVE INTERNSHIP" title="Internship details">{i?<><Row k="Status" v={i.status}/><Row k="Sector" v={i.domain}/><Row k="Mode" v={i.mode}/><Row k="Start" v={i.start_date}/><Row k="End" v={i.end_date}/><Row k="Hours / Credits" v={i.total_hours+" / "+i.credits}/></>:<p className="muted">Internship record will appear after approval.</p>}</Card>;if(tab==="Online Training")return <Training i={i} d={d} refresh={refresh}/>;if(tab==="Attendance")return <Attendance p={p} i={i} d={d} refresh={refresh}/>;if(tab==="Activities")return <Weekly p={p} i={i} d={d} refresh={refresh}/>;if(tab==="Assignments")return <Assignments d={d}/>;if(tab==="Project & Report")return <Project p={p} i={i} d={d} refresh={refresh}/>;if(tab==="Documents")return <Docs p={p} i={i} d={d} refresh={refresh}/>;if(tab==="Evaluation")return <Evaluation d={d}/>;if(tab==="Certificate")return <Completion p={p} i={i} d={d}/>;if(tab==="Final Test"||tab==="Assessments"||tab==="My Tests")return <FinalTest i={i}/>;return <Card k="WORKFLOW" title={tab}><p className="muted">This section is connected to the internship workflow and your role-based records.</p></Card>}
function Profile({p}){const[f,setF]=useState({...p}),[m,setM]=useState("");async function save(){try{await upd("profiles","id=eq."+p.id,{full_name:f.full_name,father_name:f.father_name,mother_name:f.mother_name,mobile:f.mobile,date_of_birth:f.date_of_birth,gender:f.gender,state:f.state,city:f.city,pin_code:f.pin_code,permanent_address:f.permanent_address,course:f.course,department:f.department,semester:f.semester,academic_session:f.academic_session});setM("Profile saved successfully.")}catch(e){setM(e.message)}}return <Card k="MY PROFILE" title="Personal & academic details"><div className="formGrid">{["full_name","father_name","mother_name","mobile","date_of_birth","gender","state","city","pin_code","course","department","semester","academic_session"].map(k=><Field key={k} t={k.replaceAll("_"," ")} v={f[k]} set={v=>setF({...f,[k]:v})} type={k==="date_of_birth"?"date":"text"}/>)}<label className="full">Permanent address<textarea value={f.permanent_address||""} onChange={e=>setF({...f,permanent_address:e.target.value})}/></label></div><button className="primary" onClick={save}>Save Profile</button>{m&&<div className="successBox">{m}</div>}</Card>}
